<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); foreach(File::allFiles(app_path("Models")) as $f) { $c = "App\\Models\\".str_replace("/", "\\", str_replace(".php", "", $f->getRelativePathname())); try { if(class_exists($c)) { $m = new $c; $casts = $m->getCasts(); foreach($casts as $k => $v) { if(str_contains($v, "\\") && !class_exists($v) && !enum_exists($v) && !interface_exists($v)) echo "Invalid Cast in $c: $k => $v\n"; } } } catch(Exception $e) {} }
